# Runtime motif feature generator
# Generated by Motif_Runtime_Completion. This file preserves the Phase06C SMARTS/logic feature semantics.
# Use the accompanying structural_motif_dictionary.csv and call compute_motif_features(smiles_list).
from __future__ import annotations
import pandas as pd
from rdkit import Chem, RDLogger
from rdkit.Chem import rdMolDescriptors
RDLogger.DisableLog('rdApp.*')

_COMPILED_SMARTS_CACHE = {}

def load_motif_dictionary(path):
    return pd.read_csv(path).fillna('')

def _motif_dictionary_cache_key(motif_df):
    cols = [c for c in ['motif_name', 'feature_kind', 'smarts', 'union_members'] if c in motif_df.columns]
    return tuple(tuple(str(v) for v in row) for row in motif_df[cols].itertuples(index=False, name=None))

def compile_smarts(motif_df):
    # Compiling the ~140 SMARTS expressions is expensive. The motif dictionary is
    # frozen at runtime, so compile it once and reuse the query molecules for all
    # compounds in a batch. This changes no feature semantics.
    key = _motif_dictionary_cache_key(motif_df)
    cached = _COMPILED_SMARTS_CACHE.get(key)
    if cached is not None:
        return cached
    compiled={}
    for _,row in motif_df.iterrows():
        name=row['motif_name']; kind=row['feature_kind']; smarts=str(row.get('smarts','')).strip(); mols=[]
        if kind=='smarts':
            for s in [x.strip() for x in smarts.split('||') if x.strip()]:
                q=Chem.MolFromSmarts(s)
                if q is None: raise ValueError(f'Non-compiling SMARTS for {name}: {s}')
                mols.append((s,q))
        compiled[name]=mols
    _COMPILED_SMARTS_CACHE[key] = compiled
    return compiled

def _unique_matches(mol, queries):
    out=set()
    for _,q in queries:
        if q is None: continue
        for match in mol.GetSubstructMatches(q, uniquify=True):
            out.add(tuple(sorted(int(i) for i in match)))
    return out

def _aromatic_rings(mol):
    return [tuple(sorted(r)) for r in mol.GetRingInfo().AtomRings() if r and all(mol.GetAtomWithIdx(i).GetIsAromatic() for i in r)]

def _logic_atomsets(name,mol):
    heavy=max(1,int(mol.GetNumHeavyAtoms()))
    arom_rings=_aromatic_rings(mol)
    arom_atoms=tuple(sorted(i for i,a in enumerate(mol.GetAtoms()) if a.GetIsAromatic()))
    if name=='motif_N_rich_heteroaryl':
        sets=set()
        for ring in arom_rings:
            if sum(1 for i in ring if mol.GetAtomWithIdx(i).GetAtomicNum()==7)>=2: sets.add(tuple(ring))
        return sets,float(len(sets))
    if name=='motif_aromatic_ring_count': return set(arom_rings),float(len(arom_rings))
    if name=='motif_aromatic_atom_fraction': return ({arom_atoms} if arom_atoms else set()),float(len(arom_atoms)/heavy)
    if name=='motif_fused_aromatic_present':
        fused=set()
        for i,r1 in enumerate(arom_rings):
            for r2 in arom_rings[i+1:]:
                if set(r1).intersection(r2): fused.add(tuple(sorted(set(r1).union(r2))))
        return fused,float(len(fused))
    if name=='context_rotbond_count': return set(),float(rdMolDescriptors.CalcNumRotatableBonds(mol))
    if name=='context_low_rotbond':
        n=rdMolDescriptors.CalcNumRotatableBonds(mol); return ({tuple()} if n<=3 else set()),float(n<=3)
    if name=='context_low_fraction_csp3':
        f=rdMolDescriptors.CalcFractionCSP3(mol); return ({tuple()} if f<0.25 else set()),float(f<0.25)
    if name=='motif_rigid_aromatic_context':
        nrot=rdMolDescriptors.CalcNumRotatableBonds(mol); fcsp3=rdMolDescriptors.CalcFractionCSP3(mol)
        present=bool(arom_atoms) and (nrot<=3 or fcsp3<0.25)
        return ({arom_atoms} if present and arom_atoms else set()),float(present)
    return set(),0.0

def _atom_coverage(atomsets):
    atoms=set()
    for s in atomsets: atoms.update(i for i in s if isinstance(i,int))
    return len(atoms)

def compute_motif_features(smiles_list, motif_df):
    compiled=compile_smarts(motif_df)
    rows=[]
    for smi in smiles_list:
        mol=Chem.MolFromSmiles(str(smi)) if str(smi).strip() else None
        heavy=max(1,int(mol.GetNumHeavyAtoms())) if mol is not None else 1
        atomsets_by_name={}; value_by_name={}
        for _,row in motif_df.iterrows():
            name=row['motif_name']; kind=row['feature_kind']
            if mol is None:
                atomsets_by_name[name]=set(); value_by_name[name]=0.0; continue
            if kind=='smarts':
                atomsets=_unique_matches(mol,compiled[name]); atomsets_by_name[name]=atomsets; value_by_name[name]=float(len(atomsets))
            elif kind=='logic':
                atomsets,val=_logic_atomsets(name,mol); atomsets_by_name[name]=atomsets; value_by_name[name]=val
            elif kind=='union':
                atomsets=set()
                for m in [x.strip() for x in str(row['union_members']).split(';') if x.strip()]: atomsets.update(atomsets_by_name.get(m,set()))
                atomsets_by_name[name]=atomsets; value_by_name[name]=float(len(atomsets))
            else:
                atomsets_by_name[name]=set(); value_by_name[name]=0.0
        rec={}
        for _,row in motif_df.iterrows():
            name=row['motif_name']; atomsets=atomsets_by_name[name]
            cov=_atom_coverage(atomsets); count=value_by_name.get(name,float(len(atomsets))); present=float(count>0 or cov>0)
            rec[f'{name}_present']=present; rec[f'{name}_count']=float(count); rec[f'{name}_unique_atom_count']=float(cov); rec[f'{name}_density_per_heavy_atom']=float(cov/heavy)
        rows.append(rec)
    return pd.DataFrame(rows)
